//! The MDBX reader against a database written by the real libmdbx 0.13.12 (the copy reth
//! vendors), generated by `etc/import/mdbx_fixture.c`: a plain table churned by deletes and
//! rewrites across three transactions (a three-level tree), a table of large values
//! (overflow pages), a DUPSORT table with keys holding 1, 7, 40 and 3000 duplicates (a single
//! value, sub-pages, a nested tree), and an empty table. Expected counts and digests come from
//! libmdbx's own `mdbx_dump` of the file, not from this reader.

const std = @import("std");
const testing = std.testing;

const mdbx = @import("mdbx.zig");
const Prng = @import("../../testing/prng.zig").Prng;

const fixture = @embedFile("testdata/fixture.mdbx");

const Expected = struct { name: []const u8, entries: u64, digest_hex: *const [64]u8 };

const expected = [_]Expected{
    .{
        .name = "Plain",
        .entries = 2671,
        .digest_hex = "4987558e9df53625d9ac9820f34c58bd94a63d18050a3f1cba468b6f873317d4",
    },
    .{
        .name = "Big",
        .entries = 20,
        .digest_hex = "07a813cdcfabec899c2545afe8976115b7d2493ea9456d194d0fedf91274ec27",
    },
    .{
        .name = "Dup",
        .entries = 3048,
        .digest_hex = "38ae23ab8d71a2dd0ec9f949c334c21645522b60ee5e827d6c7fff5e3f699bf1",
    },
    .{
        .name = "Empty",
        .entries = 0,
        .digest_hex = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
    },
};

/// sha256 over `u32le(key len) ++ key ++ u32le(value len) ++ value` for every entry, in
/// order (the digest `etc/import` computes from the dump), and the entry count. Checks that
/// keys, and duplicates of one key, strictly increase.
fn digest_table(reader: *mdbx.Reader, tree: *const mdbx.Tree) !struct { u64, [32]u8 } {
    var cursor = try mdbx.Cursor.init(testing.allocator, reader, tree);
    defer cursor.deinit(testing.allocator);
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var previous_key: [64]u8 = undefined;
    var previous_key_len: usize = 0;
    var previous_value: [64]u8 = undefined;
    var previous_value_len: usize = 0;
    var count: u64 = 0;
    while (try cursor.next()) |entry| : (count += 1) {
        var length: [4]u8 = undefined;
        std.mem.writeInt(u32, &length, @intCast(entry.key.len), .little);
        hasher.update(&length);
        hasher.update(entry.key);
        std.mem.writeInt(u32, &length, @intCast(entry.value.len), .little);
        hasher.update(&length);
        hasher.update(entry.value);
        if (count > 0) {
            const order = std.mem.order(u8, previous_key[0..previous_key_len], entry.key);
            try testing.expect(order != .gt);
            if (order == .eq) {
                const prior = previous_value[0..previous_value_len];
                try testing.expect(std.mem.order(u8, prior, entry.value) == .lt);
            }
        }
        @memcpy(previous_key[0..entry.key.len], entry.key);
        previous_key_len = entry.key.len;
        previous_value_len = @min(entry.value.len, previous_value.len);
        @memcpy(previous_value[0..previous_value_len], entry.value[0..previous_value_len]);
    }
    try testing.expectEqual(count, cursor.entries);
    return .{ count, hasher.finalResult() };
}

test "mdbx: every table of a libmdbx-written file reads back as libmdbx dumps it" {
    var source: mdbx.SliceSource = .{ .bytes = fixture };
    var reader = try mdbx.Reader.open(testing.allocator, source.source(), fixture.len, .{});
    defer reader.deinit(testing.allocator);
    try testing.expectEqual(@as(u32, 4096), reader.meta.page_size);
    for (expected) |want| {
        const tree = try reader.table(testing.allocator, want.name);
        try testing.expectEqual(want.entries, tree.items);
        try testing.expectEqual(std.mem.eql(u8, want.name, "Dup"), tree.dupsort());
        const count, const digest = try digest_table(&reader, &tree);
        try testing.expectEqual(want.entries, count);
        var want_digest: [32]u8 = undefined;
        _ = try std.fmt.hexToBytes(&want_digest, want.digest_hex);
        try testing.expectEqualSlices(u8, &want_digest, &digest);
    }
    try testing.expectError(error.NoTable, reader.table(testing.allocator, "Missing"));
}

test "mdbx: a torn or weak newest meta falls back to the previous steady one" {
    const copy = try testing.allocator.dupe(u8, fixture);
    defer testing.allocator.free(copy);
    var source: mdbx.SliceSource = .{ .bytes = copy };
    var reader = try mdbx.Reader.open(testing.allocator, source.source(), copy.len, .{});
    const newest = reader.meta.txnid;
    reader.deinit(testing.allocator);
    // Find the newest meta page and tear it (second txnid half differs).
    var torn: ?usize = null;
    for (0..3) |number| {
        const page = copy[number * 4096 ..][0..4096];
        if (std.mem.readInt(u64, page[28..36], .little) == newest) torn = number;
    }
    const page = copy[torn.? * 4096 ..][0..4096];
    std.mem.writeInt(u64, page[196..204], newest + 1, .little);
    var older = try mdbx.Reader.open(testing.allocator, source.source(), copy.len, .{});
    defer older.deinit(testing.allocator);
    try testing.expect(older.meta.txnid < newest);
    // A weak sign on every meta leaves nothing steady.
    for (0..3) |number| {
        std.mem.writeInt(u64, copy[number * 4096 + 188 ..][0..8], 1, .little);
    }
    const failed = mdbx.Reader.open(testing.allocator, source.source(), copy.len, .{});
    try testing.expectError(error.Corrupt, failed);
}

// Untrusted file: random byte damage anywhere must end in data or an error, never a crash,
// a hang, or a read outside the file.
test "mdbx: seeded fuzz of damaged files" {
    const copy = try testing.allocator.dupe(u8, fixture);
    defer testing.allocator.free(copy);
    var prng = Prng.init(0x6d64_6278);
    for (0..48) |_| {
        @memcpy(copy, fixture);
        const flips = prng.range(1, 64);
        for (0..flips) |_| {
            // Bias towards the used pages, where damage is reachable.
            const limit: u64 = if (prng.chance(3, 4)) 300 * 4096 else copy.len;
            copy[@intCast(prng.below(limit))] ^= @intCast(prng.range(1, 255));
        }
        var source: mdbx.SliceSource = .{ .bytes = copy };
        var reader = mdbx.Reader.open(testing.allocator, source.source(), copy.len, .{}) catch
            continue;
        defer reader.deinit(testing.allocator);
        for (expected) |want| {
            const tree = reader.table(testing.allocator, want.name) catch continue;
            var cursor = mdbx.Cursor.init(testing.allocator, &reader, &tree) catch continue;
            defer cursor.deinit(testing.allocator);
            var entries: u64 = 0;
            while (cursor.next() catch null) |_| : (entries += 1) {
                // Each entry is one node of a used page: the count is bounded by the file.
                try testing.expect(entries < copy.len);
            }
        }
    }
}
